'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dgbtf2 = require( './../lib' );


// FUNCTIONS //

/**
* Creates a bounded reset-and-factor benchmark.
*
* @private
* @param {PositiveInteger} N - column count
* @param {boolean} tall - whether to add two rows
* @param {boolean} singular - whether the first column is zero
* @returns {Function} benchmark function
*/
function createBenchmark( N, tall, singular ) {
	var original;
	var PIV;
	var AB;
	var M;
	var r;
	var c;
	var i;
	var j;

	M = ( tall ) ? N+2 : N;
	original = new Float64Array( 4*N );
	AB = new Float64Array( 4*N );
	PIV = new Int32Array( N );
	r = N;
	c = 1;
	for ( i = 0; i < original.length; i++ ) {
		original[ i ] = 999.0;
	}
	for ( j = 0; j < N; j++ ) {
		original[ (2*r)+(j*c) ] = ( singular && j === 0 ) ? 0.0 : N+4.0;
		if ( j > 0 ) {
			original[ r+(j*c) ] = 0.5;
		}
		if ( j+1 < M ) {
			original[ (3*r)+(j*c) ] = ( singular && j === 0 ) ? 0.0 : 0.25;
		}
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var expectedInfo;
		var info;
		var i;

		expectedInfo = ( singular ) ? 1 : 0;
		info = -9;
		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			// Reset the compact band input before each factorization:
			AB.set( original );
			info = dgbtf2( 'row-major', M, N, 1, 1, AB, N, PIV );
			if ( info !== expectedInfo ) {
				b.fail( 'should produce the expected factorization status' );
				break;
			}
		}
		b.toc();
		for ( i = 0; i < N; i++ ) {
			if ( PIV[ i ] !== i+1 ) {
				b.fail( 'should produce the complete identity swap history' );
				break;
			}
		}
		if ( AB[ 0 ] !== 999.0 ) {
			b.fail( 'should preserve the unused fill corner' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var options;
	var sizes;
	var name;
	var fcn;
	var i;
	var j;
	var k;

	options = {
		'iterations': 200,
		'repeats': 2
	};
	sizes = [ 8, 16 ];
	for ( i = 0; i < sizes.length; i++ ) {
		for ( j = 0; j < 2; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				name = format( '%s:N=%d:shape=%s:first=%s', pkg, sizes[ i ], ( j ) ? 'tall' : 'square', ( k ) ? 'zero' : 'positive' );
				fcn = createBenchmark( sizes[ i ], j === 1, k === 1 );
				bench( name, options, fcn );
			}
		}
	}
}

main();
